import json
from pathlib import Path
root=Path(__file__).resolve().parent
SCHEMA='../../../../.vrooli/schemas/scenario-experience-spec.schema.json'
def write(path,obj):
 p=root/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(obj,indent=2,ensure_ascii=False)+'\n')
def refs(*n):return [f'OT-P0-{i:03}' for i in n]
common={
'idle':'No operation is pending; identify the current task and available next action.',
'pending':'Work is acknowledged and queued or in flight with observed progress or an honest indeterminate state.',
'retrying':'A safe retry is actively reconciling or executing without blind duplicate side effects.',
'default':'Explain the current task, saved revision and next meaningful action.',
'loading':'Name what is loading; retain stable layout and existing local content.',
'submitting':'Acknowledge the requested operation once and prevent duplicate costly submissions.',
'saving':'Distinguish local draft changes from durably saved revision; never claim saved early.',
'syncing':'Explain local versus remote state and conflict resolution without silently overwriting edits.',
'refreshing':'Retain usable content and identify the specific information being refreshed.',
'empty':'Explain why there is no content and offer a relevant low-risk first action.',
'partial':'Show which inputs, output or services are available and which remain incomplete.',
'stale':'Show age, affected decisions and explicit refresh; never silently spend on refresh.',
'success':'Confirm the concrete durable result and offer inspection or the next task.',
'validation-error':'Associate actionable correction with each invalid field while preserving input.',
'request-error':'Explain the failed operation, preserved work and safe next action with diagnostic reference.',
'permission-denied':'Identify the unavailable operation and authority boundary without requesting unrelated access.',
'offline':'Keep supported local work usable; mark online operations unavailable and never auto-submit paid work on reconnect.',
'retry':'Explain whether retry reuses an operation identity, reconciles prior work or starts a newly authorized operation.'}
